from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json

class Links(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.active = None
        self.links = []
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = dict(attrs).get('href')
            self.active = (href, []) if href else None
    def handle_data(self, data):
        if self.active is not None:
            self.active[1].append(data)
    def handle_endtag(self, tag):
        if tag == 'a' and self.active is not None:
            href, label = self.active
            self.active = None
            url = urljoin('https://nlnet.nl/propose/', href)
            parts = urlsplit(url)
            if parts.scheme == 'https' and parts.netloc == 'nlnet.nl' and parts.path != '/propose/':
                link = {'url': url, 'label': ' '.join(''.join(label).split())}
                if link not in self.links:
                    self.links.append(link)

source = Path('products/services/nlnet-open-call-fit/raw/propose.html')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == 'e0c04ccd93223f46213027bb2157788cf3b60d864b16cbd6719a2de861b8b3a7', 'Saved proposal page differs from receipt'
parser = Links()
parser.feed(raw.decode('utf-8'))
result = {'source': str(source), 'sha256': digest, 'scope': 'Link inventory from the saved capture. Current call, eligibility and payment are unverified.', 'links': parser.links}
out = source.parent.parent / 'proposal-link-inventory.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
assert json.loads(out.read_text(encoding='utf-8')) == result
print(json.dumps({'artifact': str(out), 'links_found': len(parser.links), 'source_sha256': digest}))
